/**
 * The app, in Portuguese.
 *
 * Keyed on the ENGLISH source string, exactly as the other tables are, because
 * that is what ui() is handed at the call site. One character out and the
 * lookup misses in silence: the app draws the English and nothing anywhere
 * reports a problem.
 *
 * EUROPEAN PORTUGUESE, to match the course, which teaches pt-PT and speaks it
 * with a Portuguese voice. That decides real forms rather than spelling
 * preferences: "ecrã" not "tela", "telemóvel" not "celular", and the
 * infinitive after "a" where Brazilian would use the gerund. A reader in
 * Brazil understands all of it; the reverse would quietly teach a variety the
 * course does not.
 *
 * ADDRESS. Tu throughout, never você or o senhor, matching the German table's
 * du and the English source's plain second person — an app talking to one
 * person who chose to be here, not a form.
 */
