  "Not in a folder": "Fora de pastas",
  "Tip: in the editor, \"From catalogue\" searches every word and phrase the app already knows — genders, glosses and usage notes come with them, so you rarely have to type a card yourself.": "Dica: no editor, «Do catálogo» procura em todas as palavras e expressões que a aplicação já conhece — os géneros, os significados e as notas de uso vêm com elas, por isso raramente tens de escrever um cartão.",
