  "Paste a list": "Colar uma lista",
  "One card per line. Separate the two sides with a tab, a dash, an equals sign or a colon — a tab is what you get pasting two columns out of a spreadsheet.": "Um cartão por linha. Separa os dois lados com uma tabulação, um travessão, um sinal de igual ou dois pontos — a tabulação é o que sai ao colar duas colunas de uma folha de cálculo.",
  "Preview": "Pré-visualização",
