  "Send this set to someone": "Enviar este conjunto a alguém",
  "Copy the text below and paste it into a message. Whoever receives it pastes it back in here — it is the same format the paste box already reads.": "Copia o texto abaixo e cola-o numa mensagem. Quem o receber cola-o aqui de volta — é o mesmo formato que a caixa de colar já lê.",
  "Receive a set": "Receber um conjunto",
  "Paste a shared set here to add its cards to this one. The title and description stay as they are.": "Cola aqui um conjunto partilhado para adicionares os cartões dele a este. O título e a descrição ficam como estão.",
  "from": "de",
  "Stages": "Fases",
  "A Learn session walks each card up this ladder. Reorder or switch off whichever you like; what it takes to climb is set below.": "Uma sessão de aprendizagem sobe cada cartão por esta escada. Reordena ou desliga as que quiseres; o que é preciso para subir define-se abaixo.",
  "Remove stage": "Tirar a fase",
  "Add a stage": "Adicionar uma fase",
  "How the ladder is climbed": "Como se sobe a escada",
  "Right answers to promote": "Acertos para subir",
  "How many in a row before a card moves up a stage. One is quick; four makes you prove it.": "Quantos seguidos antes de um cartão subir de fase. Um é rápido; quatro obriga-te a prová-lo.",
  "Cards per round": "Cartões por ronda",
  "How many a Learn session asks before it stops and shows you where you got to.": "Quantos pergunta uma sessão de aprendizagem antes de parar e te mostrar até onde chegaste.",
  "A mistake costs a stage": "Um erro custa uma fase",
  "On: getting one wrong drops the card back down the ladder. Off: it only resets the streak, so a slip never undoes work.": "Ligado: falhar um faz o cartão descer a escada. Desligado: só reinicia a sequência, por isso um deslize nunca desfaz trabalho.",
  "Which side is asked": "Que lado se pergunta",
