  "Credits and licences": "Créditos e licenças",
  "Micheon is written by Leon and Michelle. These are the pieces it stands on, and the licences they are used under.": "O Micheon é escrito pelo Leon e pela Michelle. Estas são as peças em que assenta, e as licenças ao abrigo das quais são usadas.",
  "Deleted {count} entry.": "Eliminou-se {count} entrada.",
  "Deleted {count} entries.": "Eliminaram-se {count} entradas.",
  "{name} removed. Opening the course downloads it again.": "{name} removido. Ao abrires o curso, transfere-se outra vez.",
  "Could not remove {name}.": "Não foi possível remover {name}.",
  "Import replaces this profile's saved data. Shared preferences and custom words also apply to this computer's local app. Other profiles are untouched. Continue?": "A importação substitui os dados guardados deste perfil. As preferências partilhadas e as palavras próprias valem também para a aplicação local deste computador. Os outros perfis ficam intactos. Continuar?",
  "Downloaded languages": "Idiomas transferidos",
  "A language downloads itself when you open its course. Remove one to get the space back — opening the course again brings it straight back.": "Um idioma transfere-se sozinho quando abres o curso dele. Remove um para recuperares o espaço — abrir o curso outra vez trá-lo logo de volta.",
  "Space on this computer": "Espaço neste computador",
  "Recheck": "Voltar a verificar",
  "Micheon and the course": "O Micheon e o curso",
  "The program itself. Cannot be removed from in here.": "O próprio programa. Não se pode remover daqui.",
  "Your saved data": "Os teus dados guardados",
  "Progress, settings, and your own words.": "Progresso, definições e as tuas próprias palavras.",
  "Cache": "Cache",
  "Temporary files. Safe to clear.": "Ficheiros temporários. Podem limpar-se sem problema.",
  "Clearing…": "A limpar…",
