  "Disk figures are only available in the desktop app.": "Os números de disco só estão disponíveis na aplicação de computador.",
  "About languages: the German course is built into the program rather than installed separately, so there is nothing to uninstall that would save you space. The other languages are not here yet, and take up nothing.": "Sobre os idiomas: o curso de alemão vem dentro do programa em vez de se instalar à parte, por isso não há nada para desinstalar que te poupasse espaço. Os outros idiomas ainda não estão cá, e não ocupam nada.",
  "Move your Micheon data": "Leva contigo os teus dados do Micheon",
  "Take your progress, settings, custom words, mastery and installed pets to another computer with a private JSON file.": "Leva o teu progresso, as definições, as tuas palavras, o domínio e as mascotes instaladas para outro computador com um ficheiro JSON privado.",
  "Exporting…": "A exportar…",
