  "Import data": "Importar dados",
  "Import replaces this profile's saved data. Shared preferences and custom words also apply to this computer's local app. Other profiles are untouched.": "A importação substitui os dados guardados deste perfil. As preferências partilhadas e as palavras próprias valem também para a aplicação local deste computador. Os outros perfis ficam intactos.",
  "What Micheon is storing for you": "O que o Micheon guarda de ti",
