  "Everything above, for this account on this device. Your account stays, and other profiles on this computer are untouched. This cannot be undone.": "Tudo o que está acima, para esta conta neste dispositivo. A tua conta fica, e os outros perfis deste computador ficam intactos. Isto não se pode desfazer.",
