  "Your own words and phrases": "As tuas próprias palavras e expressões",
  "Anything you add here is taught like the rest of the course — it shows up in Continue learning, lessons and tests.": "Tudo o que adicionares aqui é ensinado como o resto do curso — aparece em Continuar a aprender, nas lições e nos exames.",
  "Pack": "Pacote",
  "Rename pack": "Mudar o nome do pacote",
  "Delete “{name}” and its {count} entries?": "Eliminar «{name}» e as suas {count} entradas?",
