  "New pack name": "Nome do pacote novo",
  "How hard this pack is, so it is served at the right time.": "O quão difícil é este pacote, para ser servido na altura certa.",
  "New pack": "Pacote novo",
  "This only decides when the pack gets served, so an honest guess is enough.": "Isto só decide quando o pacote é servido, por isso basta um palpite honesto.",
  "German": "Alemão",
  "Note (optional)": "Nota (opcional)",
  "Hide bulk upload": "Ocultar o carregamento em massa",
  "Upload a whole list": "Carregar uma lista inteira",
  "One per line: German, then English. Separate them with a tab, a comma, = or a dash.": "Um por linha: alemão e depois inglês. Separa-os com uma tabulação, uma vírgula, = ou um travessão.",
  "ready": "prontas",
  "unreadable": "ilegíveis",
  "…and {count} more": "…e mais {count}",
  "That is as many as a pack holds.": "É tudo o que cabe num pacote.",
  "Lessons": "Lições",
  "Work through practical {language} in short blocks: read, listen, choose, type, and translate.": "Trabalha {language} prático em blocos curtos: ler, ouvir, escolher, escrever e traduzir.",
  "core modules": "módulos principais",
  "practice sets": "conjuntos de prática",
  "Search lessons, topics or a {language} word…": "Procura lições, temas ou uma palavra em {language}…",
  "Lesson content": "Conteúdo da lição",
  "Hide finished ({count})": "Ocultar as terminadas ({count})",
  "Clear filters": "Limpar os filtros",
  "Finished lessons are put away — nothing is deleted, and any whose words have started to fade stay in the list so you can review them.": "As lições terminadas ficam arrumadas — não se apaga nada, e as que têm palavras a começar a desvanecer ficam na lista para as poderes rever.",
  "Show finished ({count})": "Mostrar as terminadas ({count})",
  "Select lessons": "Selecionar lições",
  "Deselect all": "Anular toda a seleção",
  "Select all {count} shown": "Selecionar as {count} mostradas",
  "Select lessons to pause several at once": "Seleciona lições para pausares várias de uma vez",
  "Pause selected": "Pausar o selecionado",
  "Resume selected": "Retomar o selecionado",
  "Nothing matches that": "Nada corresponde a isso",
  "Try a different word, or clear the filters to see every lesson again.": "Experimenta outra palavra, ou limpa os filtros para veres outra vez todas as lições.",
  "Open": "Abrir",
  "Paused": "Em pausa",
  "Finished": "Terminadas",
  "{count} of the items you learned here are past their review date, so you are assumed to have forgotten some of them. Answering them once each puts them back to full.": "{count} dos elementos que aprendeste aqui já passaram da data de revisão, por isso assume-se que te esqueceste de parte deles. Responder a cada um uma vez repõe-nos por inteiro.",
  "{count} fading": "{count} a desvanecer",
  "learned": "aprendidas",
  "Conversation coverage": "Cobertura de conversa",
  "The current path covers greetings, daily routines, travel, food, questions, basic opinions, and common sentence patterns.": "O percurso atual cobre cumprimentos, rotinas diárias, viagens, comida, perguntas, opiniões básicas e estruturas de frase comuns.",
  "Your mastery": "O teu domínio",
  "{count} items": "{count} elementos",
  "remaining": "restantes",
  "Deselect": "Anular a seleção",
  "Select": "Selecionar",
  "Play {language} audio": "Reproduzir o áudio em {language}",
  "German picks a different \"you\" for friends, for a group, and for politeness. English uses one word for all three.": "O alemão escolhe um «tu» diferente para os amigos, para um grupo e para a cortesia. O inglês usa uma só palavra para os três.",
  "Graded in Listen mode — exposure only, not mastery.": "Avaliado no modo de escuta — só exposição, não domínio.",
  "Known": "Sabido",
  "Struggle": "Difícil",
  "To learn": "Por aprender",
  "Memory strength": "Força da memória",
  "Click a bar to set it directly.": "Clica numa barra para a definires diretamente.",
  "Come back in {days} day (level {level} of 5)": "Volta daqui a {days} dia (nível {level} de 5)",
  "Come back in {days} days (level {level} of 5)": "Volta daqui a {days} dias (nível {level} de 5)",
  "never reviewed again": "nunca mais se revê",
  "Its review is due today. Answer it once and it counts in full again, on a longer interval.": "A revisão é hoje. Responde uma vez e volta a contar por inteiro, com um intervalo maior.",
  "due for review": "revisão para hoje",
  "{days} days past its review, so you are assumed to still recall {kept}% of it — that is how much it counts towards your total right now. It halves every {halfLife} days towards {floor}% and never drops below that. Getting it right once puts it back to 100%.": "{days} dias depois da revisão, por isso assume-se que ainda recordas {kept} % — é isso que conta para o teu total neste momento. Reduz-se a metade a cada {halfLife} dias em direção a {floor} % e nunca desce abaixo disso. Acertar uma vez repõe-o a 100 %.",
  "{days} days overdue · {kept}% remembered": "{days} dias de atraso · {kept} % recordado",
  "review in": "revisão daqui a",
  "days short": "dias a menos",
  "How this count works": "Como funciona esta contagem",
  "{count} item is fading right now.": "{count} elemento está a desvanecer neste momento.",
  "{count} items are fading right now.": "{count} elementos estão a desvanecer neste momento.",
  "Show them": "Mostrá-los",
  "This number is an estimate of what you'd remember right now — not a tally of everything you have ever seen.": "Este número é uma estimativa do que recordarias neste momento — não uma contagem de tudo o que já viste.",
  "Something you learned recently counts as a whole item. Something you have not seen for a long time counts as less, because you probably remember less of it. That is why the number can go down as well as up.": "Uma coisa que aprendeste há pouco conta como um elemento inteiro. Uma coisa que não vês há muito tempo conta menos, porque é provável que recordes menos dela. É por isso que o número tanto pode descer como subir.",
  "For example: you had “Guten Morgen” down two months ago and have not seen it since, so it counts as 0.8 rather than 1. Answer it correctly once and it counts fully again, immediately.": "Por exemplo: sabias «Guten Morgen» há dois meses e não voltaste a vê-lo, por isso conta 0,8 em vez de 1. Acerta uma vez e volta a contar por inteiro, de imediato.",
  "The more times you have recalled something correctly, the more slowly it slips. And nothing ever falls to zero — coming back to a word you once knew is far quicker than meeting it new.": "Quantas mais vezes tiveres recordado bem uma coisa, mais devagar ela te escapa. E nada chega a zero — voltar a uma palavra que já soubeste é muito mais rápido do que conhecê-la de novo.",
  "“Due” means today is its review day. “Fading” means that day has been and gone. Same items, just later — which is why a row shows one or the other, never both.": "«Revisão para hoje» quer dizer que hoje é o dia de a rever. «A desvanecer» quer dizer que esse dia já passou. São os mesmos elementos, só que mais tarde — e é por isso que uma linha mostra um ou outro, nunca os dois.",
  "Never fades: starred items, words you marked mastered by hand, and anything you learned outside the app — there is no review schedule to measure those against. This is the same number your dashboard, profile and games use.": "Nunca desvanecem: os elementos com estrela, as palavras que marcaste como dominadas à mão e tudo o que aprendeste fora da aplicação, porque não há um calendário de revisões com que os medir. É o mesmo número que o teu painel, o teu perfil e os jogos usam.",
  "Word & sentence tracker": "Acompanhamento de palavras e frases",
  "Loading your vocabulary catalog…": "A carregar o teu catálogo de vocabulário…",
