  "A score here changes nothing in your lessons — picking from four is recognition, and the lessons ask you to produce the word. It is a read on how the listening is going.": "Uma nota aqui não muda nada nas tuas lições — escolher entre quatro é reconhecimento, e as lições pedem-te para produzires a palavra. É só uma leitura de como vai a escuta.",
