  "Master the German articles! Guide your snake to consume words that match your target. Watch out for world boundaries and enemy bots!": "Domina os artigos alemães! Leva a tua serpente a comer as palavras que correspondem ao teu alvo. Cuidado com os limites do mundo e com os bots inimigos!",
