  "Move your mouse to steer. Hold click or Space to boost speed (costs score). Eat words matching the Target Article to grow. Avoid hitting Bots! If a bot hits your body, you get bonus points.": "Move o rato para te dirigires. Mantém o clique ou o Espaço para acelerares (custa pontos). Come as palavras que correspondem ao artigo alvo para cresceres. Não batas nos bots! Se um bot bater no teu corpo, ganhas pontos extra.",
