  "Practise the short, natural forms people use. Full forms stay visible and count as correct.": "Pratica as formas curtas e naturais que as pessoas usam. As formas completas continuam à vista e contam como certas.",
  "Practise complete standard forms for formal writing, careful listening, and test answers.": "Pratica as formas padrão completas para escrita formal, escuta atenta e respostas de exame.",
  "Low": "Baixo",
  "Normal": "Normal",
