  "Drag this header to detach and place it anywhere.": "Arrasta este cabeçalho para o separares e o pores onde quiseres.",
  "You can change answers to earlier questions.": "Podes mudar as respostas a perguntas anteriores.",
  "No pet messages yet": "Ainda não há mensagens da mascote",
  "Tips and questions will appear here after the mascot speaks.": "As dicas e as perguntas aparecem aqui depois de a mascote falar.",
  "Yes": "Sim",
  "No": "Não",
  "Let's practise some German.": "Vamos praticar um bocado de alemão.",
  "Los geht's! Let's go.": "Los geht's! Vamos lá.",
  "German tip: when a word uses der, die, or das, learn them together — say “der Tisch”, not just “Tisch”.": "Dica de alemão: quando uma palavra leva der, die ou das, aprende-os juntos — diz «der Tisch», e não só «Tisch».",
  "German tip: in a normal German sentence, the verb comes second — “Heute gehe ich nach Hause.”": "Dica de alemão: numa frase alemã normal, o verbo vem em segundo lugar — «Heute gehe ich nach Hause».",
  "German tip: after weil or dass, put the verb at the end — “weil ich müde bin”.": "Dica de alemão: depois de weil ou dass, põe o verbo no fim — «weil ich müde bin».",
  "German tip: German words for people, places, things, or ideas always start with a capital letter.": "Dica de alemão: as palavras alemãs para pessoas, lugares, coisas ou ideias começam sempre por maiúscula.",
  "German tip: some verbs split in two — “aufstehen” becomes “Ich stehe um sieben auf.”": "Dica de alemão: alguns verbos partem-se em dois — «aufstehen» passa a «Ich stehe um sieben auf».",
  "English tip: normal sentences usually put who or what first, then the action, then the rest — “I read the book.”": "Dica de inglês: as frases normais costumam pôr primeiro quem ou o quê, depois a ação e depois o resto — «I read the book».",
  "English tip: after can, must, should, or will, use the verb without “to” — “can go”, not “can to go”.": "Dica de inglês: depois de can, must, should ou will, usa o verbo sem «to» — «can go», e não «can to go».",
  "English tip: for habits or facts, verbs with he, she, or it usually end in -s — “she works”, “he knows”.": "Dica de inglês: para hábitos ou factos, os verbos com he, she ou it costumam acabar em -s — «she works», «he knows».",
  "English tip: describing words normally come before the thing — “a red car”. They stay the same — “a nice man”, “a nice woman”.": "Dica de inglês: as palavras que descrevem vêm normalmente antes da coisa — «a red car». Não mudam: «a nice man», «a nice woman».",
  "English tip: choose “a” or “an” by sound, not spelling — “a university”, but “an hour”.": "Dica de inglês: escolhe «a» ou «an» pelo som, não pela ortografia — «a university», mas «an hour».",
  "English tip: after “didn't”, use go, see, or do — not went, saw, or did: “I didn't go.”": "Dica de inglês: depois de «didn't», usa go, see ou do — e não went, saw ou did: «I didn't go».",
  "English tip: “cannot” is one word. Its short form is “can't”.": "Dica de inglês: «cannot» é uma só palavra. A forma curta é «can't».",
  "English tip: “will not” becomes “won't”, never “willn't”.": "Dica de inglês: «will not» passa a «won't», nunca «willn't».",
  "English tip: German “es gibt” becomes “there is” for one thing and “there are” for several — never “it gives”.": "Dica de inglês: o alemão «es gibt» diz-se «there is» para uma coisa e «there are» para várias — nunca «it gives».",
  "English tip: when talking about the past, use “there was” for one thing and “there were” for several.": "Dica de inglês: a falar do passado, usa «there was» para uma coisa e «there were» para várias.",
  "English tip: do not use two negatives together — “I didn't see anything”, not “I didn't see nothing”.": "Dica de inglês: não uses duas negações juntas — «I didn't see anything», e não «I didn't see nothing».",
  "English tip: “should not” becomes “shouldn't”. The same shortening gives “wouldn't”, “couldn't”, and “mustn't”.": "Dica de inglês: «should not» passa a «shouldn't». A mesma redução dá «wouldn't», «couldn't» e «mustn't».",
  "English tip: use “haven't” with I, you, we, or they, and “hasn't” with he, she, or it — “I haven't seen it yet”.": "Dica de inglês: usa «haven't» com I, you, we ou they, e «hasn't» com he, she ou it — «I haven't seen it yet».",
