  "Right now: {words} words + {sentences} sentences = {total} cards at a time, each heard {passes}×. The first {total} play {passes} times over, then the next {total} do the same.": "Agora: {words} palavras + {sentences} frases = {total} cartões de cada vez, cada um ouvido {passes}×. Os primeiros {total} passam {passes} vezes e depois os {total} seguintes fazem o mesmo.",
  "Right now: {total} cards at a time, each heard {passes}×. The first {total} play {passes} times over, then the next {total} do the same.": "Agora: {total} cartões de cada vez, cada um ouvido {passes}×. Os primeiros {total} passam {passes} vezes e depois os {total} seguintes fazem o mesmo.",
  "Words and sentences": "Palavras e frases",
  "Words only": "Só palavras",
  "Sentences and phrases only": "Só frases e expressões",
  "Straight away": "De imediato",
  "After a few hours": "Ao fim de umas horas",
  "After a day": "Ao fim de um dia",
  "When the review says so": "Quando a revisão disser",
  "No wait at all. Anything can play again the moment the order reaches it — which on a narrow filter can mean the same handful of cards all evening. Right for a first pass through a new pack, and not much else.": "Sem espera nenhuma. Qualquer coisa pode tocar outra vez mal a ordem lá chegue — o que, com um filtro estreito, pode dar o mesmo punhado de cartões a noite toda. Serve para uma primeira passagem por um pacote novo, e para pouco mais.",
  "About four hours. Long enough that you have to remember it rather than recognise it from a minute ago, and short enough to meet it again the same day.": "Cerca de quatro horas. O suficiente para teres de o recordar em vez de o reconheceres de há um minuto, e pouco o bastante para o voltares a encontrar no mesmo dia.",
  "A full day. This is the shortest gap the review ladder ever asks for, and the point at which hearing something again is recall rather than an echo.": "Um dia inteiro. É o intervalo mais curto que a escada de revisões alguma vez pede, e o ponto em que voltar a ouvir uma coisa é recordá-la e não um eco.",
  "Nothing you have answered correctly comes back until the review ladder says it is due — one day, then three, ten, thirty, a hundred and eighty. Anything you have heard but never answered waits a day.": "Nada que tenhas acertado volta antes de a escada de revisões dizer que é altura — um dia, depois três, dez, trinta, cento e oitenta. O que ouviste mas nunca respondeste espera um dia.",
