  "The pictures beside the words. Around eight hundred of them ship with the app, so they look the same on every machine and work with no connection.": "As imagens ao lado das palavras. Cerca de oitocentas vêm com a aplicação, por isso ficam iguais em qualquer máquina e funcionam sem ligação.",
  "Tatoeba": "Tatoeba",
  "Part of the real-sentence practice. Most of the course is written for Micheon, and the share coming from here falls with every pack that replaces it.": "Parte da prática com frases reais. A maior parte do curso é escrita para o Micheon, e a fatia que vem daqui desce com cada pacote que a substitui.",
