  "Also stay over fullscreen games, watch-only — clicks pass straight through. Some machines still give the game up a frame for anything drawn over it.": "Também ficam por cima dos jogos em ecrã inteiro, só para ver — os cliques passam ao lado. Mesmo assim, algumas máquinas tiram ao jogo um fotograma por qualquer coisa desenhada por cima.",
  "🌱 I'm new to coding": "🌱 Sou novo na programação",
