  "C1 · Advanced": "C1 · avançado",
  "Fluent and precise, including work, study and abstract subjects.": "Fluente e preciso, incluindo trabalho, estudos e temas abstratos.",
  "C2 · Near-native": "C2 · quase nativo",
  "Anything a native handles: idiom, nuance, humour, fast speech.": "Tudo o que um nativo aguenta: idiomatismos, matizes, humor, fala rápida.",
  "All items": "Todos os elementos",
