  "Specialist / casual": "Especializado / informal",
  "Extra practice": "Prática extra",
  "Swallow a German city. Everything you eat teaches you its name.": "Engole uma cidade alemã. Tudo o que comes ensina-te o nome.",
  "Checking in on each other": "Saber um do outro",
  "French voice is muted and will be skipped.": "A voz francesa está silenciada e vai ser saltada.",
  "French repeats": "Repetições em francês",
  "French first": "Francês primeiro",
  "Your turn — say it in French": "É a tua vez — di-lo em francês",
  "Your turn to say the French before it is spoken": "É a tua vez de dizer o francês antes de ele ser dito",
  "French words to arrange": "Palavras francesas para ordenar",
  "Portuguese words to arrange": "Palavras portuguesas para ordenar",
  "Portuguese tip: the article belongs with the noun — a casa, o trabalho, a cidade.": "Dica de português: o artigo anda com o nome — a casa, o trabalho, a cidade.",
  "Portuguese tip: ão is a very common nasal ending — listen for it in words such as não and estação.": "Dica de português: ão é uma terminação nasal muito comum — repara nela em palavras como não e estação.",
  "Portuguese tip: ç is pronounced like s before a, o and u — as in começar.": "Dica de português: o ç lê-se como s antes de a, o e u — como em começar.",
  "Portuguese tip: estar is used for states and locations, while ser is used for identity and more lasting characteristics.": "Dica de português: estar usa-se para estados e lugares, e ser para a identidade e as características mais duradouras.",
  "Polish voice is muted and will be skipped.": "A voz polaca está silenciada e vai ser saltada.",
  "Polish repeats": "Repetições em polaco",
  "Polish first": "Polaco primeiro",
  "Your turn — say it in Polish": "É a tua vez — di-lo em polaco",
  "Your turn to say the Polish before it is spoken": "É a tua vez de dizer o polaco antes de ele ser dito",
  "Polish words to arrange": "Palavras polacas para ordenar",
  "Polish tip: there are no articles at all — “dom” is house, a house and the house, all at once.": "Dica de polaco: não há artigos nenhuns — «dom» é casa, uma casa e a casa, tudo ao mesmo tempo.",
  "Polish tip: a negated verb takes the genitive — “lubię kawę”, but “nie lubię kawy”.": "Dica de polaco: um verbo negado pede genitivo — «lubię kawę», mas «nie lubię kawy».",
  "Polish tip: the ending already says who — “idę” is I am going, so “ja idę” puts the stress on the I.": "Dica de polaco: a terminação já diz quem — «idę» é eu vou, por isso «ja idę» põe a ênfase no eu.",
  "Polish tip: verbs come in pairs — “robić” is doing it, “zrobić” is getting it done.": "Dica de polaco: os verbos vêm aos pares — «robić» é estar a fazê-lo, «zrobić» é deixá-lo feito.",
  "Polish tip: to a stranger it is Pan or Pani, never ty — “Czy mówi Pan po angielsku?”.": "Dica de polaco: a um desconhecido é Pan ou Pani, nunca ty — «Czy mówi Pan po angielsku?».",
  "Polish tip: the stress is almost always on the second-to-last syllable — dzię-KU-ję, ksią-ŻKA.": "Dica de polaco: a tónica cai quase sempre na penúltima sílaba — dzię-KU-ję, ksią-ŻKA.",
  "Polish tip: “ó” and “u” sound identical, and so do “rz” and “ż” — which is why Polish children are drilled on them too.": "Dica de polaco: «ó» e «u» soam exatamente igual, e «rz» e «ż» também — e é por isso que também as crianças polacas as treinam à exaustão.",
  "Polish tip: nouns change their ending for their job in the sentence — “to jest kawa”, but “piję kawę”.": "Dica de polaco: os nomes mudam de terminação conforme a função na frase — «to jest kawa», mas «piję kawę».",
  "Spanish voice is muted and will be skipped.": "A voz espanhola está silenciada e vai ser saltada.",
  "Italian voice is muted and will be skipped.": "A voz italiana está silenciada e vai ser saltada.",
  "Spanish repeats": "Repetições em espanhol",
  "Italian repeats": "Repetições em italiano",
  "Spanish first": "Espanhol primeiro",
  "Italian first": "Italiano primeiro",
  "Your turn — say it in Spanish": "É a tua vez — di-lo em espanhol",
  "Your turn — say it in Italian": "É a tua vez — di-lo em italiano",
  "Your turn to say the Spanish before it is spoken": "É a tua vez de dizer o espanhol antes de ele ser dito",
  "Your turn to say the Italian before it is spoken": "É a tua vez de dizer o italiano antes de ele ser dito",
  "Spanish words to arrange": "Palavras espanholas para ordenar",
  "Italian words to arrange": "Palavras italianas para ordenar",
  "Russian words to arrange": "Palavras russas para ordenar",
  "{target} is ready to type. You can answer either box first; a correct {target} answer moves focus to {meaning}.": "{target} está pronto para escreveres. Podes responder a qualquer uma das caixas primeiro; uma resposta certa em {target} passa o foco para {meaning}.",
  "French tip: a noun comes with le or la, and there is no rule that always works — learn them together, “la table”, not just “table”.": "Dica de francês: um nome vem com le ou la, e não há regra que funcione sempre — aprende-os juntos, «la table», e não só «table».",
  "French tip: in speech the “ne” of a negation usually disappears — “Je sais pas”. Keep it when you write.": "Dica de francês: na fala, o «ne» da negação costuma desaparecer — «Je sais pas». Mantém-no quando escreves.",
  "French tip: describing words normally come after the thing — “une voiture rouge” — but petit, grand, bon, beau and jeune go in front.": "Dica de francês: as palavras que descrevem vêm normalmente depois da coisa — «une voiture rouge» — mas petit, grand, bon, beau e jeune vão à frente.",
  "French tip: “tu” is for one person you know; “vous” is for a stranger, someone older, or several people at once.": "Dica de francês: «tu» é para uma pessoa que conheces; «vous» é para um desconhecido, alguém mais velho, ou várias pessoas ao mesmo tempo.",
  "French tip: an adjective agrees with what it describes — “il est content”, “elle est contente”, “elles sont contentes”.": "Dica de francês: o adjetivo concorda com o que descreve — «il est content», «elle est contente», «elles sont contentes».",
  "French tip: most verbs use avoir in the past — “j’ai mangé” — but aller, venir, partir and the rest of the coming-and-going verbs use être.": "Dica de francês: a maioria dos verbos usa avoir no passado — «j’ai mangé» — mas aller, venir, partir e os restantes verbos de ir e vir usam être.",
  "French tip: “à” and “de” glue onto le and les — à + le is “au”, de + les is “des”. Never write “à le”.": "Dica de francês: «à» e «de» colam-se a le e les — à + le é «au», de + les é «des». Nunca escrevas «à le».",
  "French tip: a question can just be a statement said upwards — “Tu viens ?” is as correct as “Est-ce que tu viens ?”.": "Dica de francês: uma pergunta pode ser só uma afirmação dita a subir — «Tu viens ?» é tão correto como «Est-ce que tu viens ?».",
  "Learning progress": "Progresso da aprendizagem",
  "Everything you have learned, your review schedule, streak and XP.": "Tudo o que aprendeste, o teu calendário de revisões, a sequência e os XP.",
  "Lesson history": "Histórico de lições",
  "The record of individual sittings behind the activity chart.": "O registo de cada sessão que está por trás do gráfico de atividade.",
  "Your own words and packs": "As tuas próprias palavras e pacotes",
  "Anything you typed in yourself. Nothing here can be recovered.": "Tudo o que escreveste tu. Nada disto se pode recuperar.",
  "Game high scores": "Recordes dos jogos",
  "Best scores from the practice games. Safe to clear.": "As melhores pontuações dos jogos de prática. Podem apagar-se sem problema.",
  "Settings and appearance": "Definições e aspeto",
  "Theme, accent colour, voice and learning preferences.": "Tema, cor de destaque, voz e preferências de aprendizagem.",
