  "Odds and ends Micheon keeps that do not fit the groups above.": "Coisas soltas que o Micheon guarda e que não encaixam nos grupos acima.",
  "Cache cleared.": "Cache limpa.",
  "Could not clear the cache.": "Não foi possível limpar a cache.",
  "{count} more words & phrases until you're {fluent} — able to keep up with real natives. Next stage: “{stage}”.": "Mais {count} palavras e expressões até seres {fluent} — capaz de acompanhar nativos a sério. Etapa seguinte: «{stage}».",
  "{count} to {milestone}: {detail}": "{count} para {milestone}: {detail}",
  "Both the German and the English are needed.": "São precisos o alemão e o inglês.",
  "Added — it will come up in Continue learning.": "Adicionado — vai aparecer em Continuar a aprender.",
  "You already have that one.": "Esse já o tens.",
  "Nothing could be read from that.": "Não se conseguiu ler nada disso.",
  "After 3 more cards": "Ao fim de mais 3 cartões",
  "After 10 more cards": "Ao fim de mais 10 cartões",
  "After 30 more cards": "Ao fim de mais 30 cartões",
  "Three other cards go by first. Short enough that you are still holding the word when it comes back, which is the exercise short-term memory actually is.": "Passam antes outros três cartões. Pouco, o suficiente para ainda teres a palavra na cabeça quando ela volta — e é isso mesmo que o exercício da memória de curto prazo é.",
  "Ten other cards go by first. Far enough that you have to fetch the word back rather than still be carrying it, and near enough to do it several times in one sitting.": "Passam antes outros dez cartões. Longe o suficiente para teres de ir buscar a palavra em vez de a continuares a carregar, e perto o suficiente para o fazeres várias vezes na mesma sessão.",
  "Thirty other cards go by first. About a session's worth on a narrow filter, so a word returns once you have genuinely moved on from it.": "Passam antes outros trinta cartões. Com um filtro estreito, cerca de uma sessão inteira, por isso uma palavra volta quando já passaste mesmo à frente dela.",
  "Feedback and wishes": "Comentários e desejos",
  "Say what is missing, what got in the way, or what you would like next.": "Diz o que falta, o que atrapalhou ou o que gostarias a seguir.",
  "What did you notice, and what would you like?": "O que notaste e o que gostarias?",
  "What are you looking for?": "O que procuras?",
  "Here are your friends.": "Aqui estão os teus amigos.",
  "Fast track": "Via rápida",
  "Straight to talking": "Direto a falar",
  "Only what a conversation needs — greetings, reactions, plans, family, food. No rooms, no furniture.": "Só o que uma conversa precisa — cumprimentos, reações, planos, família, comida. Nada de divisões nem mobília.",
  "Topic round": "Ronda por tema",
  "Words for a subject": "Palavras para um tema",
  "A subject like family or food — pick every word and phrase you'd use for it, then see what you missed.": "Um tema como a família ou a comida — escolhe todas as palavras e frases que usarias e depois vê o que te escapou.",
  "Back to Learn": "Voltar a Aprender",
  "Which of these would you use when talking about {subject}?": "Quais destes usarias ao falar sobre {subject}?",
  "Tap everything that fits, then check.": "Toca em tudo o que se encaixa e depois verifica.",
