  "Order": "Ordem",
  "Levels": "Níveis",
  "Similar sentences together": "Frases parecidas juntas",
  "The course's pick": "A escolha do curso",
  "How Continue learning is put together": "Como Continuar a aprender é montado",
  "The course's pick blends how common a sentence is with how hard it is and how far you are. Easiest first takes all of one level before the next. Most common first takes what people say most, whatever the level. Similar sentences together takes the next sentence and then every sentence that starts the same way — all the “Ich möchte …”, then all the “Kannst du …”. Conversation order takes an exchange as the dialogues have it — a question, then the answer that fits it, then what comes next. Shortest first and Longest first go by length. Reviews come back whatever the order.": "A escolha do curso junta o quão comum é uma frase, o quão difícil é e até onde chegaste. Mais fáceis primeiro leva um nível inteiro antes do seguinte. Mais comuns primeiro leva o que as pessoas mais dizem, seja qual for o nível. Frases parecidas juntas leva a frase seguinte e depois todas as que começam da mesma forma — todos os “Ich möchte …”, depois todos os “Kannst du …”. Ordem de conversa leva uma troca tal como os diálogos a têm — uma pergunta, depois a resposta que encaixa, depois o que vem a seguir. Mais curtas primeiro e Mais longas primeiro vão por comprimento. As revisões voltam seja qual for a ordem.",
  "Order decides what comes first and still teaches everything. This decides what a sitting draws on at all, so you can work through one level and stop. Reviews are never held back.": "A ordem decide o que vem primeiro e mesmo assim ensina tudo. Isto decide de que é que uma sessão se serve, para poderes percorrer um nível e parar. As revisões nunca ficam retidas.",
  "Conversation order": "Ordem de conversa",
  "Changing this rebuilds the sitting from the start.": "Mudar isto volta a montar a sessão desde o início.",

